// Complete, in-memory handoff. Clinical reports are regenerated by MoonBit.
import { invoke, makeSession, readSession, sourceFingerprint } from "./workbench.mjs";
import { createBundle } from "./delivery.mjs";
import { encodeReviewNotes, readReviewNotes, reviewProgress } from "./review-notes.mjs";
import { readZip, writeZip, ZIP_LIMITS } from "./archive.mjs";

export const HANDOFF_LIMITS = Object.freeze({ sessionBytes: 2 * 1024 * 1024, notesBytes: 4 * 1024 * 1024, manifestBytes: 32768 });
const REPORTS = ["report.html", "audit.json", "audit.csv", "chart.svg", "manifest.json"];
const NAMES = ["session.json", "review-notes.json", ...REPORTS.map(name => "report/" + name)];
const encoder = new TextEncoder();
const exact = (value, keys) => value && !Array.isArray(value) && typeof value === "object" &&
  Object.keys(value).length === keys.length && keys.every(k => Object.hasOwn(value, k));
const isHash = value => typeof value === "string" && /^[0-9a-f]{64}$/.test(value);
const timestamp = value => typeof value === "string" && /^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{3}Z$/.test(value) &&
  Number.isFinite(Date.parse(value)) && new Date(value).toISOString() === value;
function fail(code, message) { const error = new Error(message); error.code = code; throw error; }
async function hash(text) {
  const bytes = new Uint8Array(await crypto.subtle.digest("SHA-256", encoder.encode(text)));
  return Array.from(bytes, b => b.toString(16).padStart(2, "0")).join("");
}
const order = files => [...files].sort((a, b) => NAMES.indexOf(a.name) - NAMES.indexOf(b.name));

function manifestPayload(value) {
  if (!exact(value, ["schema_version", "kind", "scope", "created_at", "files"]) || value.schema_version !== 1 ||
      value.kind !== "lesion-followup-handoff" || value.scope !== "target_lesions_only" || !timestamp(value.created_at) ||
      !Array.isArray(value.files) || ![6, 7].includes(value.files.length)) fail("handoff_schema", "交接清单的类型、版本或字段不受支持。");
  const seen = new Set();
  const files = value.files.map(file => {
    if (!exact(file, ["name", "byte_length", "sha256"]) || !NAMES.includes(file.name) || seen.has(file.name) ||
        !Number.isSafeInteger(file.byte_length) || file.byte_length < 0 || file.byte_length > ZIP_LIMITS.entryBytes || !isHash(file.sha256)) {
      fail("handoff_schema", "交接清单的文件名、大小或摘要不符合要求。");
    }
    seen.add(file.name);
    return { name: file.name, byte_length: file.byte_length, sha256: file.sha256 };
  });
  if (!NAMES.filter(name => name !== "review-notes.json").every(name => seen.has(name))) fail("handoff_schema", "交接清单缺少会话或报告文件。");
  return { schema_version: 1, kind: "lesion-followup-handoff", scope: "target_lesions_only", created_at: value.created_at, files: order(files) };
}

async function manifestText(files, created_at) {
  const entries = await Promise.all(files.map(async file => ({ name: file.name, byte_length: encoder.encode(file.content).length, sha256: await hash(file.content) })));
  const payload = manifestPayload({ schema_version: 1, kind: "lesion-followup-handoff", scope: "target_lesions_only", created_at, files: entries });
  return JSON.stringify({ ...payload, sha256: await hash(JSON.stringify(payload)) }, null, 2) + "\n";
}

function checkLimits(files) {
  for (const file of files) {
    const limit = file.name === "session.json" ? HANDOFF_LIMITS.sessionBytes : file.name === "review-notes.json" ? HANDOFF_LIMITS.notesBytes : ZIP_LIMITS.entryBytes;
    if (encoder.encode(file.content).length > limit) fail("handoff_limits", `${file.name} 超出交接包大小限制。`);
  }
}

export async function createHandoff(evaluate, before, current, language, notes = null, created_at = new Date().toISOString()) {
  // Session decoding gives this operation its own immutable source strings.
  const sessionText = await makeSession(before, current, language, created_at);
  if (encoder.encode(sessionText).length > HANDOFF_LIMITS.sessionBytes) fail("handoff_limits", "交接会话超过 2 MiB，请拆分记录后重试。");
  const session = await readSession(sessionText);
  const report = createBundle(evaluate, session.current, session.language);
  const files = [{ name: "session.json", content: sessionText }];
  if (notes !== null) {
    const content = await encodeReviewNotes(notes);
    await readReviewNotes(content, evaluate, session.current);
    files.push({ name: "review-notes.json", content });
  }
  files.push(...report.files.map(file => ({ name: "report/" + file.name, content: file.content })));
  checkLimits(files);
  files.push({ name: "handoff.json", content: await manifestText(files, created_at) });
  return writeZip(files);
}

export async function readHandoff(evaluate, bytes) {
  const entries = await readZip(bytes), files = new Map(entries.map(file => [file.name, file.content]));
  const text = files.get("handoff.json");
  if (!text || encoder.encode(text).length > HANDOFF_LIMITS.manifestBytes) fail("handoff_schema", "未找到有效的交接清单，请选择工作区导出的完整交接 ZIP。");
  let value;
  try { value = JSON.parse(text); } catch { fail("handoff_schema", "交接清单不是有效 JSON。"); }
  if (!exact(value, ["schema_version", "kind", "scope", "created_at", "files", "sha256"]) || !isHash(value.sha256)) fail("handoff_schema", "交接清单缺少有效的完整性摘要。");
  const { sha256, ...fields } = value, manifest = manifestPayload(fields);
  if (await hash(JSON.stringify(manifest)) !== sha256) fail("handoff_integrity", "交接清单与完整性摘要不一致。");
  if (files.size !== manifest.files.length + 1 || entries.some(file => file.name !== "handoff.json" && !manifest.files.some(f => f.name === file.name))) {
    fail("handoff_files", "交接包存在缺失或清单之外的文件。");
  }
  checkLimits(entries.filter(file => file.name !== "handoff.json"));
  for (const file of manifest.files) {
    const content = files.get(file.name);
    if (content === undefined || encoder.encode(content).length !== file.byte_length || await hash(content) !== file.sha256) fail("handoff_integrity", "文件内容与清单不一致：" + file.name);
  }
  const session = await readSession(files.get("session.json"));
  if (session.saved_at !== manifest.created_at) fail("handoff_schema", "会话与交接清单的打包时间不一致。");
  const artifacts = REPORTS.filter(name => name !== "manifest.json").map(name => ({ name, content: files.get("report/" + name) }));
  const checked = invoke(evaluate, { action: "verify-bundle", manifest: files.get("report/manifest.json"), files: artifacts });
  if (!checked.ok) fail("handoff_bundle", "交接报告未通过原有报告包校验，请核对文件完整性。");
  const regenerated = createBundle(evaluate, session.current, session.language);
  if (regenerated.files.some(file => files.get("report/" + file.name) !== file.content)) {
    fail("handoff_replay", "交接报告与当前版本重新生成的结果不一致，未载入任何记录。");
  }
  const notes = files.has("review-notes.json") ? await readReviewNotes(files.get("review-notes.json"), evaluate, session.current) : null;
  const editor = invoke(evaluate, { action: "editor", ...session.current });
  const summary = { study_id: editor.result.study.study_id, baseline_date: editor.result.study.baseline_date,
    visit_count: regenerated.quality.visit_count, hint_count: regenerated.quality.review_hints.length,
    has_reference: session.before !== null, language: session.language, notes: notes ? reviewProgress(notes) : null,
    source_sha256: await sourceFingerprint(session.current), manifest_sha256: sha256, created_at: manifest.created_at, file_count: files.size };
  return { session, notes, summary };
}

// Validate completely before handing a single snapshot to the UI's synchronous apply.
export function createHandoffReceiver(evaluate, getRevision, apply) {
  let serial = 0, ready = null;
  const invalidate = () => { serial++; ready = null; };
  return {
    invalidate,
    async inspect(readBytes) {
      invalidate();
      const token = serial, revision = getRevision();
      const guard = () => { if (token !== serial || revision !== getRevision()) fail("handoff_stale", "工作区或所选文件已变化，请重新检查交接包。"); };
      const bytes = await readBytes(); guard();
      const snapshot = await readHandoff(evaluate, bytes); guard();
      ready = { snapshot, revision };
      return structuredClone(snapshot.summary);
    },
    canLoad() { return ready !== null && ready.revision === getRevision(); },
    load() {
      if (!ready || ready.revision !== getRevision()) { invalidate(); fail("handoff_stale", "交接预览已失效，请重新检查后再载入。"); }
      const snapshot = structuredClone(ready.snapshot);
      invalidate(); apply(snapshot);
    },
  };
}
